import { test, after } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { pathToFileURL } from 'node:url';

const root = process.cwd();
const StyleDictionary = (await import(pathToFileURL(path.join(root, 'lib/StyleDictionary.js')).href))
  .default;

// Runtime fixtures: asset files whose base64 output contains +, / and = padding.
const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'sd-base64-quote-'));
const buildPath = `${path.join(tmp, 'build')}/`;
const iconPath = path.join(tmp, 'icon-bytes.bin');
const logoPath = path.join(tmp, 'logo-bytes.bin');
const ICON_BYTES = Buffer.from([0xfb, 0xff, 0xff, 0x00]);
const LOGO_BYTES = Buffer.from([0xff, 0xff, 0xff, 0x01]);
fs.writeFileSync(iconPath, ICON_BYTES);
fs.writeFileSync(logoPath, LOGO_BYTES);
const iconBase64 = ICON_BYTES.toString('base64');
const logoBase64 = LOGO_BYTES.toString('base64');

after(() => fs.rmSync(tmp, { recursive: true, force: true }));

// Premise of the ticket: base64 output routinely contains +, / and = padding.
assert.ok(
  iconBase64.includes('+') && iconBase64.includes('/') && iconBase64.endsWith('='),
  `fixture base64 must contain +, / and = padding, got: ${iconBase64}`,
);

const sd = new StyleDictionary({
  tokens: {
    asset: {
      icon: { delete: { value: iconPath, type: 'asset' } },
      image: { logo: { value: logoPath, type: 'asset' } },
    },
    color: { base: { red: { value: '#ff0000', type: 'color' } } },
  },
  platforms: {
    web: {
      transforms: ['name/kebab', 'asset/base64'],
      buildPath,
      files: [
        { destination: 'out.scss', format: 'scss/variables' },
        { destination: 'out.css', format: 'css/variables' },
        { destination: 'out.less', format: 'less/variables' },
        { destination: 'out.styl', format: 'stylus/variables' },
      ],
    },
  },
});
await sd.buildAllPlatforms();

const read = (name) => fs.readFileSync(path.join(buildPath, name), 'utf8');

// Returns the single declaration line that defines the given variable name.
const lineFor = (out, varName) =>
  out
    .split('\n')
    .map((l) => l.trim())
    .find((l) => l.includes(varName) && !l.trimStart().startsWith('//') && !l.includes('/*'));

test('scss/variables emits each base64 asset value as a double-quoted string literal', () => {
  const out = read('out.scss');
  const iconLine = lineFor(out, '$asset-icon-delete');
  const logoLine = lineFor(out, '$asset-image-logo');
  assert.ok(
    iconLine && iconLine.includes(`"${iconBase64}"`),
    `expected the $asset-icon-delete declaration to be a double-quoted string literal containing "${iconBase64}"\n--- output ---\n${out}`,
  );
  assert.ok(
    logoLine && logoLine.includes(`"${logoBase64}"`),
    `expected the $asset-image-logo declaration to be a double-quoted string literal containing "${logoBase64}"\n--- output ---\n${out}`,
  );
});

test('css/variables emits each base64 asset value as a double-quoted string literal', () => {
  const out = read('out.css');
  const iconLine = lineFor(out, '--asset-icon-delete');
  const logoLine = lineFor(out, '--asset-image-logo');
  assert.ok(
    iconLine && iconLine.includes(`"${iconBase64}"`),
    `expected the --asset-icon-delete declaration to be a double-quoted string literal containing "${iconBase64}"\n--- output ---\n${out}`,
  );
  assert.ok(
    logoLine && logoLine.includes(`"${logoBase64}"`),
    `expected the --asset-image-logo declaration to be a double-quoted string literal containing "${logoBase64}"\n--- output ---\n${out}`,
  );
});

test('less/variables emits each base64 asset value as a double-quoted string literal', () => {
  const out = read('out.less');
  const iconLine = lineFor(out, '@asset-icon-delete');
  const logoLine = lineFor(out, '@asset-image-logo');
  assert.ok(
    iconLine && iconLine.includes(`"${iconBase64}"`),
    `expected the @asset-icon-delete declaration to be a double-quoted string literal containing "${iconBase64}"\n--- output ---\n${out}`,
  );
  assert.ok(
    logoLine && logoLine.includes(`"${logoBase64}"`),
    `expected the @asset-image-logo declaration to be a double-quoted string literal containing "${logoBase64}"\n--- output ---\n${out}`,
  );
});

test('stylus/variables emits each base64 asset value as a double-quoted string literal', () => {
  const out = read('out.styl');
  const iconLine = lineFor(out, '$asset-icon-delete');
  const logoLine = lineFor(out, '$asset-image-logo');
  assert.ok(
    iconLine && iconLine.includes(`"${iconBase64}"`),
    `expected the $asset-icon-delete declaration to be a double-quoted string literal containing "${iconBase64}"\n--- output ---\n${out}`,
  );
  assert.ok(
    logoLine && logoLine.includes(`"${logoBase64}"`),
    `expected the $asset-image-logo declaration to be a double-quoted string literal containing "${logoBase64}"\n--- output ---\n${out}`,
  );
});

import { test, after } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { pathToFileURL } from 'node:url';
import { compileString } from 'sass';
import less from 'less';

const root = process.cwd();
const StyleDictionary = (await import(pathToFileURL(path.join(root, 'lib/StyleDictionary.js')).href))
  .default;

// Runtime fixture: asset file whose base64 output contains +, / and = padding.
const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'sd-base64-compile-'));
const buildPath = `${path.join(tmp, 'build')}/`;
const iconPath = path.join(tmp, 'icon-bytes.bin');
const ICON_BYTES = Buffer.from([0xfb, 0xff, 0xff, 0x00]);
fs.writeFileSync(iconPath, ICON_BYTES);
const iconBase64 = ICON_BYTES.toString('base64');

after(() => fs.rmSync(tmp, { recursive: true, force: true }));

assert.ok(
  iconBase64.includes('+') && iconBase64.includes('/') && iconBase64.endsWith('='),
  `fixture base64 must contain +, / and = padding, got: ${iconBase64}`,
);

const sd = new StyleDictionary({
  tokens: {
    asset: { icon: { delete: { value: iconPath, type: 'asset' } } },
  },
  platforms: {
    web: {
      transforms: ['name/kebab', 'asset/base64'],
      buildPath,
      files: [
        { destination: 'out.scss', format: 'scss/variables' },
        { destination: 'out.less', format: 'less/variables' },
      ],
    },
  },
});
await sd.buildAllPlatforms();

const read = (name) => fs.readFileSync(path.join(buildPath, name), 'utf8');

// The compiled CSS must yield the base64 payload as a string value (either quote
// style), which requires the generated declaration to be a quoted string literal.
const yieldsQuotedPayload = (css) =>
  css.includes(`"${iconBase64}"`) || css.includes(`'${iconBase64}'`);

test('generated SCSS compiles without errors and yields the full base64 value unchanged', () => {
  const scss = read('out.scss');
  // Throws on a parse error -> test fails, which is what we want when the
  // base64 value (+, /, = characters) is emitted unquoted.
  const result = compileString(`${scss}\n.probe { content: $asset-icon-delete; }\n`);
  assert.ok(
    yieldsQuotedPayload(result.css),
    `expected compiled CSS to contain the full base64 payload as a string value\n--- source ---\n${scss}\n--- compiled ---\n${result.css}`,
  );
});

test('generated LESS compiles without errors and yields the full base64 value unchanged', async () => {
  const lessSrc = read('out.less');
  // Rejects on a parse error -> test fails when the value is emitted unquoted.
  const result = await less.render(`${lessSrc}\n.probe { content: @asset-icon-delete; }`);
  assert.ok(
    yieldsQuotedPayload(result.css),
    `expected compiled CSS to contain the full base64 payload as a string value\n--- source ---\n${lessSrc}\n--- compiled ---\n${result.css}`,
  );
});

import { test, after } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { pathToFileURL } from 'node:url';

const root = process.cwd();
const StyleDictionary = (await import(pathToFileURL(path.join(root, 'lib/StyleDictionary.js')).href))
  .default;

const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'sd-asset-unchanged-'));
const buildPath = `${path.join(tmp, 'build')}/`;

after(() => fs.rmSync(tmp, { recursive: true, force: true }));

const sd = new StyleDictionary({
  tokens: {
    asset: {
      // value produced by the asset/url transform: a CSS function call
      icon: { delete: { value: 'assets/icons/delete.svg', type: 'asset' } },
      // value that already contains its own quoting
      quoted: { value: '"pre-quoted-string"', type: 'asset' },
    },
  },
  platforms: {
    urlPlatform: {
      transforms: ['name/kebab', 'asset/url'],
      buildPath,
      files: [
        {
          destination: 'url.scss',
          format: 'scss/variables',
          filter: (token) => token.name === 'asset-icon-delete',
        },
      ],
    },
    quotedPlatform: {
      transforms: ['name/kebab'],
      buildPath,
      files: [
        {
          destination: 'quoted.scss',
          format: 'scss/variables',
          filter: (token) => token.name === 'asset-quoted',
        },
      ],
    },
  },
});
await sd.buildAllPlatforms();

const read = (name) => fs.readFileSync(path.join(buildPath, name), 'utf8');

test('asset/url values are emitted unchanged and never wrapped in a second set of quotes', () => {
  const out = read('url.scss');
  assert.ok(
    out.includes('$asset-icon-delete: url("assets/icons/delete.svg");'),
    `expected scss output to contain $asset-icon-delete: url("assets/icons/delete.svg");\n--- output ---\n${out}`,
  );
  assert.ok(
    !out.includes('"url('),
    `expected asset/url value not to be wrapped in extra quotes\n--- output ---\n${out}`,
  );
});

test('asset values that already contain their own quoting are emitted unchanged', () => {
  const out = read('quoted.scss');
  assert.ok(
    out.includes('$asset-quoted: "pre-quoted-string";'),
    `expected scss output to contain $asset-quoted: "pre-quoted-string";\n--- output ---\n${out}`,
  );
  assert.ok(
    !out.includes('""pre-quoted-string""'),
    `expected already-quoted asset value not to be wrapped in a second set of quotes\n--- output ---\n${out}`,
  );
});

import { test, after } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { pathToFileURL } from 'node:url';

const root = process.cwd();
const StyleDictionary = (await import(pathToFileURL(path.join(root, 'lib/StyleDictionary.js')).href))
  .default;

// Runtime fixture: asset file whose base64 output contains +, / and = padding.
const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'sd-base64-jsonjs-'));
const buildPath = `${path.join(tmp, 'build')}/`;
const iconPath = path.join(tmp, 'icon-bytes.bin');
const ICON_BYTES = Buffer.from([0xfb, 0xff, 0xff, 0x00]);
fs.writeFileSync(iconPath, ICON_BYTES);
const iconBase64 = ICON_BYTES.toString('base64');

after(() => fs.rmSync(tmp, { recursive: true, force: true }));

const sd = new StyleDictionary({
  tokens: {
    asset: { icon: { delete: { value: iconPath, type: 'asset' } } },
  },
  platforms: {
    jsonPlatform: {
      transforms: ['name/kebab', 'asset/base64'],
      buildPath,
      files: [{ destination: 'tokens.json', format: 'json/flat' }],
    },
    jsPlatform: {
      transforms: ['name/camel', 'asset/base64'],
      buildPath,
      files: [{ destination: 'tokens.mjs', format: 'javascript/es6' }],
    },
  },
});
await sd.buildAllPlatforms();

const jsonText = fs.readFileSync(path.join(buildPath, 'tokens.json'), 'utf8');
const parsed = JSON.parse(jsonText);
const jsModule = await import(pathToFileURL(path.join(buildPath, 'tokens.mjs')).href);

test('json/flat contains the raw base64 value without extra quoting', () => {
  assert.equal(
    parsed['asset-icon-delete'],
    iconBase64,
    `expected json/flat value to be the raw base64 string, got: ${JSON.stringify(parsed['asset-icon-delete'])}`,
  );
  // data URI embedding keeps working: the token value is the payload itself
  assert.equal(
    `data:image/png;base64,${parsed['asset-icon-delete']}`,
    `data:image/png;base64,${iconBase64}`,
  );
});

test('javascript/es6 contains the raw base64 value without extra quoting', () => {
  assert.equal(
    jsModule.assetIconDelete,
    iconBase64,
    `expected javascript/es6 export to be the raw base64 string, got: ${JSON.stringify(jsModule.assetIconDelete)}`,
  );
  assert.equal(
    `data:image/png;base64,${jsModule.assetIconDelete}`,
    `data:image/png;base64,${iconBase64}`,
  );
});

import { test, after } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { pathToFileURL } from 'node:url';

const root = process.cwd();
const StyleDictionary = (await import(pathToFileURL(path.join(root, 'lib/StyleDictionary.js')).href))
  .default;

const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'sd-non-asset-'));
const buildPath = `${path.join(tmp, 'build')}/`;

after(() => fs.rmSync(tmp, { recursive: true, force: true }));

const sd = new StyleDictionary({
  tokens: {
    color: { red: { value: '#ff0000', type: 'color' } },
    str: { message: { value: 'Hello World', type: 'string' } },
  },
  platforms: {
    web: {
      transforms: ['name/kebab', 'asset/base64'],
      buildPath,
      files: [
        { destination: 'out.scss', format: 'scss/variables' },
        { destination: 'out.css', format: 'css/variables' },
        { destination: 'out.less', format: 'less/variables' },
        { destination: 'out.styl', format: 'stylus/variables' },
      ],
    },
  },
});
await sd.buildAllPlatforms();

const read = (name) => fs.readFileSync(path.join(buildPath, name), 'utf8');

// Returns the declaration line that defines the given variable name.
const lineFor = (out, varName) =>
  out
    .split('\n')
    .map((l) => l.trim())
    .find((l) => l.includes(varName) && !l.startsWith('//') && !l.includes('/*'));

const expectUnquoted = (label, out, varName, rawValue) => {
  const line = lineFor(out, varName);
  assert.ok(
    line,
    `expected a declaration for ${varName} in ${label}\n--- output ---\n${out}`,
  );
  assert.ok(
    line.includes(rawValue),
    `expected the ${varName} declaration to contain the unchanged value ${rawValue}\n--- line ---\n${line}\n--- output ---\n${out}`,
  );
  assert.ok(
    !line.includes(`"${rawValue}"`) && !line.includes(`'${rawValue}'`),
    `expected the non-asset ${varName} value not to be quoted in ${label}\n--- line ---\n${line}\n--- output ---\n${out}`,
  );
};

test('color tokens are unchanged in all CSS-family variable formats', () => {
  expectUnquoted('scss', read('out.scss'), '$color-red', '#ff0000');
  expectUnquoted('css', read('out.css'), '--color-red', '#ff0000');
  expectUnquoted('less', read('out.less'), '@color-red', '#ff0000');
  expectUnquoted('stylus', read('out.styl'), '$color-red', '#ff0000');
});

test('plain string tokens are unchanged in all CSS-family variable formats', () => {
  expectUnquoted('scss', read('out.scss'), '$str-message', 'Hello World');
  expectUnquoted('css', read('out.css'), '--str-message', 'Hello World');
  expectUnquoted('less', read('out.less'), '@str-message', 'Hello World');
  expectUnquoted('stylus', read('out.styl'), '$str-message', 'Hello World');
});
